import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

async function getCardStats() {
  const res = await fetch('https://api.example.com/dashboard/stats')
  return res.json() as Promise<{ totalRevenue: number; totalInvoices: number }>
}

async function getRevenue() {
  const res = await fetch('https://api.example.com/dashboard/revenue')
  return res.json() as Promise<{ month: string; amount: number }[]>
}

async function getLatestInvoices() {
  const res = await fetch('https://api.example.com/dashboard/invoices')
  return res.json() as Promise<{ id: string; name: string; amount: number }[]>
}

async function CardStatsSection() {
  const data = await getCardStats()
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartSection() {
  const revenue = await getRevenue()
  return <RevenueChart revenue={revenue} />
}

async function LatestInvoicesSection() {
  const invoices = await getLatestInvoices()
  return <LatestInvoices invoices={invoices} />
}

function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card skeleton">
        <h2>Total Revenue</h2>
        <p>—</p>
      </div>
      <div className="card skeleton">
        <h2>Total Invoices</h2>
        <p>—</p>
      </div>
    </div>
  )
}

function RevenueChartSkeleton() {
  return (
    <div className="chart skeleton">
      <h2>Revenue</h2>
      <ul>
        <li>—</li>
        <li>—</li>
        <li>—</li>
      </ul>
    </div>
  )
}

function LatestInvoicesSkeleton() {
  return (
    <div className="invoices skeleton">
      <h2>Latest Invoices</h2>
      <ul>
        <li>—</li>
        <li>—</li>
        <li>—</li>
      </ul>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsSection />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChartSection />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoicesSection />
      </Suspense>
    </main>
  )
}
